use std::{collections::BTreeMap,fs,path::Path};
#[derive(Default)]pub struct Lock{pub version:u32,pub packages:BTreeMap<String,Package>}
#[derive(Clone,Default)]pub struct Package{pub source:String,pub revision:String,pub checksum:String}
pub fn checksum(data:&[u8])->String{let mut h=14695981039346656037u64;for b in data{h^=*b as u64;h=h.wrapping_mul(1099511628211);}format!("{h:016x}")}
pub fn load(path:&Path)->Result<Lock,String>{if !path.exists(){return Ok(Lock{version:1,packages:BTreeMap::new()})}let text=fs::read_to_string(path).map_err(|e|e.to_string())?;let mut lock=Lock{version:1,packages:BTreeMap::new()};let mut current=None;for raw in text.lines(){let line=raw.trim();if line.is_empty()||line.starts_with('#'){continue}if let Some(v)=line.strip_prefix("version="){lock.version=v.parse().map_err(|_|"invalid lockfile version")?;continue}if line.starts_with('[')&&line.ends_with(']'){let name=line[1..line.len()-1].to_string();lock.packages.entry(name.clone()).or_default();current=Some(name);continue}let Some((key,value))=line.split_once('=')else{return Err(format!("invalid lockfile line: {line}"))};let Some(name)=current.as_ref()else{return Err("package property outside package section".into())};let package=lock.packages.get_mut(name).unwrap();match key.trim(){"source"=>package.source=value.trim().to_string(),"revision"=>package.revision=value.trim().to_string(),"checksum"=>package.checksum=value.trim().to_string(),other=>return Err(format!("unknown lockfile key: {other}"))}}Ok(lock)}
pub fn save(path:&Path,lock:&Lock)->Result<(),String>{let mut out=format!("# Kalcite lockfile - generated, do not edit\nversion={}\n",lock.version.max(1));for(name,p)in&lock.packages{out.push_str(&format!("\n[{name}]\nsource={}\nrevision={}\nchecksum={}\n",p.source,p.revision,p.checksum));}fs::write(path,out).map_err(|e|e.to_string())}
pub fn verify(lock:&Lock,cache:&Path)->Result<(),String>{for(name,p)in&lock.packages{if p.revision.is_empty(){return Err(format!("package `{name}` is not pinned to a revision"))}let path=cache.join(name);if path.is_file()&&!p.checksum.is_empty(){let got=checksum(&fs::read(&path).map_err(|e|e.to_string())?);if got!=p.checksum{return Err(format!("checksum mismatch for `{name}`"))}}}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn hash_stable(){assert_eq!(checksum(b"abc"),checksum(b"abc"));}}
